pub static DOOR_PROJECTED_FIELDS: &[crate::kernel::ProjectedFieldSpec] = &[];

impl Door {
    pub fn extract_id(v: &crate::kernel::Json) -> Result<String, crate::kernel::Refusal> {
        let by_identity = (|| -> Option<String> {
            let c0 = v.dig("tool.value")?.to_id_component().ok()?;
            Some(c0)
        })();
        let by_id_key = v.get("id").and_then(|j| j.to_id_component().ok());
        let by_reference_key = v.get("door").and_then(|j| j.to_id_component().ok());

        by_identity
            .or(by_id_key)
            .or(by_reference_key)
            .ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Door: no identity found (tried tool.value, id, door)".to_string(),
                )
            })
    }
}

fn door_invariants() -> crate::kernel::InvariantSet {
    crate::kernel::InvariantSet {
        aggregate: vec![],
        entities: vec![],
    }
}

