#[derive(Debug, Clone)]
pub struct ServeArgs {
    pub tool: ReaderTool,
    pub dispatch: Option<DispatchTool>,
    pub denied: Option<DeniedArgument>,
    pub path: Option<PathArgument>,
    pub r#ref: Option<RefArgument>,
}

pub fn dispatch_serve(
    repo: &mut impl crate::kernel::Repository<Door>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: ServeArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Door> {
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, DOOR_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                crate::kernel::Hydrate::Act {
                    id: __route.aggregate().to_string(),
                }
            }
            None => {
                let __hydrate_id: String = args.tool.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Door {
                        tool: Some(args.tool.clone()),
                        dispatch: args.dispatch.clone(),
                        denied: args.denied.clone(),
                        path: args.path.clone(),
                        r#ref: args.r#ref.clone(),
                    }),
                    state_independent: false,
                }
            }
        },
        "Serve",
        "Governance::Door",
        "Door",
        "tool.value",
        &with_references,
        &[],
        None,
        |record| {
            let _ = record;
            Ok(())
        },
        &[],
        &door_invariants(),
        &["ToolServed"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

impl ServeArgs {
    pub fn to_json(&self) -> crate::kernel::Json {
        crate::kernel::Json::Object(
            vec![
                ("tool".to_string(), self.tool.to_json()),
                (
                    "dispatch".to_string(),
                    self.dispatch
                        .as_ref()
                        .map_or(crate::kernel::Json::Null, |v| v.to_json()),
                ),
                (
                    "denied".to_string(),
                    self.denied
                        .as_ref()
                        .map_or(crate::kernel::Json::Null, |v| v.to_json()),
                ),
                (
                    "path".to_string(),
                    self.path
                        .as_ref()
                        .map_or(crate::kernel::Json::Null, |v| v.to_json()),
                ),
                (
                    "ref".to_string(),
                    self.r#ref
                        .as_ref()
                        .map_or(crate::kernel::Json::Null, |v| v.to_json()),
                ),
            ]
            .into_iter()
            .filter(|(_, v)| !matches!(v, crate::kernel::Json::Null))
            .collect(),
        )
    }
}

impl ServeArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "ServeArgs expects an object, got {}",
                v.inspect()
            )));
        }
        let unknown = v.unknown_keys(&["tool", "dispatch", "denied", "path", "ref", "id"]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            return Err(crate::kernel::Refusal::UnknownArgument(
                crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                    command: "Serve",
                    unknown: &unknown,
                    declared: &["tool", "dispatch", "denied", "path", "ref"],
                }
                .render_args(),
            ));
        }
        let required: &[&str] = &["tool"];
        let absent: Vec<&str> = required
            .iter()
            .copied()
            .filter(|key| v.get(key).is_none())
            .collect();
        if !absent.is_empty() {
            return Err(crate::kernel::Refusal::AbsentArgument(
                crate::kernel::refusal_wording::AbsentArgumentAbsentArgsArgs {
                    command: "Serve",
                    absent: &absent,
                    declared: &["tool", "dispatch", "denied", "path", "ref"],
                }
                .render_args(),
            ));
        }
        let tool = ReaderTool::from_json(
            &(match v.get("tool").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Serve.tool expects ReaderTool, got nil".to_string(),
                )
            })? {
                crate::kernel::Json::Null => crate::kernel::Json::Object(Vec::new()),
                other => other.clone(),
            })
            .coerce_single_field("value"),
        )?;
        let dispatch = match v.get("dispatch") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(DispatchTool::from_json(&x.coerce_single_field("value"))?),
        };
        let denied = match v.get("denied") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(DeniedArgument::from_json(&x.coerce_single_field("value"))?),
        };
        let path = match v.get("path") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(PathArgument::from_json(&x.coerce_single_field("value"))?),
        };
        let r#ref = match v.get("ref") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(RefArgument::from_json(&x.coerce_single_field("value"))?),
        };
        Ok(Self {
            tool,
            dispatch,
            denied,
            path,
            r#ref,
        })
    }
}

impl ServeArgs {
    pub fn decode_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "ServeArgs expects an object, got {}",
                v.inspect()
            )));
        }
        Ok(())
    }

    pub fn refuse_unknown_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        let unknown = v.unknown_keys(&["tool", "dispatch", "denied", "path", "ref", "id"]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            crate::kernel::collecting::refuse_each(&unknown, |names| {
                crate::kernel::Refusal::UnknownArgument(
                    crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                        command: "Serve",
                        unknown: names,
                        declared: &["tool", "dispatch", "denied", "path", "ref"],
                    }
                    .render_args(),
                )
            })?;
        }
        Ok(())
    }

    pub fn refuse_absent_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        let required: &[&str] = &["tool"];
        let absent: Vec<&str> = required
            .iter()
            .copied()
            .filter(|key| v.get(key).is_none())
            .collect();
        if !absent.is_empty() {
            crate::kernel::collecting::refuse_each(&absent, |names| {
                crate::kernel::Refusal::AbsentArgument(
                    crate::kernel::refusal_wording::AbsentArgumentAbsentArgsArgs {
                        command: "Serve",
                        absent: names,
                        declared: &["tool", "dispatch", "denied", "path", "ref"],
                    }
                    .render_args(),
                )
            })?;
        }
        Ok(())
    }
}

/// This aggregate's state, or one of its events' payloads, as a caller is answered with
/// it: each single-field value object as its bare field (the shape a command takes it in).
pub fn present(state: crate::kernel::Json) -> crate::kernel::Json {
    match state {
        crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(
            fields
                .into_iter()
                .map(|(k, v)| {
                    let new_v = match k.as_str() {
                        "tool" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "dispatch" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "denied" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "path" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "ref" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        _ => v,
                    };
                    (k, new_v)
                })
                .collect(),
        ),
        other => other,
    }
}
